package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.AfterMapping;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingTarget;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.time.LocalDate;
import java.util.Collection;
import java.util.List;
import java.util.Map;

/**
 * Maps Owner &amp; OwnerDto using Mapstruct.
 *
 * <p>Declared as an abstract class (rather than a plain interface) so the derived
 * {@code bulkSignupWarning} field can consult the {@link OwnerRepository} for the
 * count of owners already registered today.
 */
@Mapper(uses = PetMapper.class)
public abstract class OwnerMapper {

    /** Fixed city-to-region lookup used to derive an owner's locality. */
    static final Map<String, String> CITY_REGION = Map.of(
        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** More than this many owners registered on a single day raises the bulk-signup warning. */
    private static final long BULK_SIGNUP_THRESHOLD = 80L;

    @Autowired
    protected OwnerRepository ownerRepository;

    public abstract OwnerDto toOwnerDto(Owner owner);

    /**
     * Fills the presentation-only {@code displayName} as {@code "LastName, FirstName"}
     * from the stored names, once MapStruct has mapped the remaining fields.
     */
    @AfterMapping
    void addDisplayName(Owner owner, @MappingTarget OwnerDto ownerDto) {
        ownerDto.setDisplayName(owner.getLastName() + ", " + owner.getFirstName());
    }

    /**
     * Fills the presentation-only {@code initials} as the upper-cased first letters of
     * firstName and lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
     */
    @AfterMapping
    void addInitials(Owner owner, @MappingTarget OwnerDto ownerDto) {
        ownerDto.setInitials(
            Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".");
    }

    /**
     * Fills the presentation-only {@code membershipNumber} as {@code '<customerCode>-M<YY>'}
     * where YY is the last two digits of the registrationDate year. Left null when either
     * source field is missing.
     */
    @AfterMapping
    void addMembershipNumber(Owner owner, @MappingTarget OwnerDto ownerDto) {
        if (owner.getCustomerCode() != null && owner.getRegistrationDate() != null) {
            String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
            ownerDto.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
        }
    }

    /**
     * Fills the presentation-only {@code membershipTier}: {@code 'SILVER'} when
     * namesakeCount is 0 and an email is present, otherwise {@code 'BRONZE'}.
     */
    @AfterMapping
    void addMembershipTier(Owner owner, @MappingTarget OwnerDto ownerDto) {
        boolean silver = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0
            && owner.getEmail() != null && !owner.getEmail().isEmpty();
        ownerDto.setMembershipTier(silver ? "SILVER" : "BRONZE");
    }

    /**
     * Fills the presentation-only {@code locality} as the canonical region derived from
     * the owner's city via the fixed {@link #CITY_REGION} table, or {@code 'UNKNOWN'}
     * when the city is not in the table.
     */
    @AfterMapping
    void addLocality(Owner owner, @MappingTarget OwnerDto ownerDto) {
        ownerDto.setLocality(CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN"));
    }

    /**
     * Fills the presentation-only {@code bulkSignupWarning}: {@code true} once more than
     * {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered on the current day
     * (the same daily accumulation the per-day create limit is based on), otherwise
     * {@code false}.
     */
    @AfterMapping
    void addBulkSignupWarning(Owner owner, @MappingTarget OwnerDto ownerDto) {
        LocalDate today = LocalDate.now();
        long registeredToday = ownerRepository.findAll().stream()
            .filter(existing -> today.equals(existing.getRegistrationDate()))
            .count();
        ownerDto.setBulkSignupWarning(registeredToday > BULK_SIGNUP_THRESHOLD);
    }

    public abstract Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    public abstract Owner toOwner(OwnerFieldsDto ownerDto);

    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

